const extracted = $input.first().json;
const rawText = typeof extracted.text === 'string' ? extracted.text : '';
const promptText = 'TAREA: FACTURA\nExtrae de esta factura colombiana: proveedor, nit, fecha (YYYY-MM-DD), subtotal, iva, total (enteros en COP) e items. Responde SOLO JSON.\nTexto de la factura:\n' + rawText;
return [{ json: { rawText, promptText } }];

const built = $('Build Invoice Prompt').first().json;
const llmResponse = $input.first().json;
let parsed = {};
try {
  const content = (llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message && llmResponse.choices[0].message.content) || '{}';
  parsed = JSON.parse(content);
} catch (err) {
  parsed = {};
}

const errors = [];
const providerName = typeof parsed.proveedor === 'string' && parsed.proveedor.trim() ? parsed.proveedor.trim() : null;
const providerNit = typeof parsed.nit === 'string' && parsed.nit.trim() ? parsed.nit.trim() : null;
const invoiceDateRaw = typeof parsed.fecha === 'string' ? parsed.fecha.trim() : null;
const subtotal = Number.isFinite(parsed.subtotal) ? parsed.subtotal : null;
const iva = Number.isFinite(parsed.iva) ? parsed.iva : null;
const total = Number.isFinite(parsed.total) ? parsed.total : null;
const items = Array.isArray(parsed.items) ? parsed.items : [];

if (!providerName) errors.push('proveedor is required');
if (!providerNit) errors.push('nit is required');
if (subtotal === null) errors.push('subtotal is required');
if (iva === null) errors.push('iva is required');
if (total === null) errors.push('total is required');

const datePattern = /^\d{4}-\d{2}-\d{2}$/;
let dateValid = false;
if (invoiceDateRaw && datePattern.test(invoiceDateRaw)) {
  const [y, m, d] = invoiceDateRaw.split('-').map(Number);
  const parsedDate = new Date(Date.UTC(y, m - 1, d));
  dateValid = parsedDate.getUTCFullYear() === y && parsedDate.getUTCMonth() === m - 1 && parsedDate.getUTCDate() === d;
}
if (!invoiceDateRaw) {
  errors.push('fecha is required');
} else if (!dateValid) {
  errors.push('fecha is invalid');
}

if (subtotal !== null && iva !== null && total !== null) {
  if (Math.abs(total - (subtotal + iva)) > 1) {
    errors.push('total does not match subtotal + iva');
  }
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    providerName,
    providerNit,
    invoiceDate: dateValid ? invoiceDateRaw : null,
    subtotal,
    iva,
    total,
    items,
    rawText: built.rawText,
  },
}];

